#!/bin/sh
# Writes src/builtin.inc, the C front end's catalogue of built-in
# functions, keywords and predefined preprocessor symbols, from the Go
# reference's internal/builtin (catalog_gen.go, generated by
# tools/mkbuiltin from the Icon sources, and gcon.go, gcon's additions).
# Functions and keywords are merged and sorted by name (in bytes), as
# the Go's init does. Run from the repository root; needed only while
# the Go is the reference (the C will then generate the table from the
# Icon sources itself).
set -eu
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

# Each entry as "kind TAB name TAB C initialiser", kind f, k or p.
awk '
# golit: the Go string literal at the start of s (with its quotes)
function golit(s,   i, c) {
	for (i = 2; i <= length(s); i++) {
		c = substr(s, i, 1)
		if (c == "\\") i++
		else if (c == "\"") return substr(s, 1, i)
	}
	return s
}
# field: the value of "Key: " in entry e ("" if absent): a literal, or
# a word up to "," or "}"
function field(e, key,   i, v) {
	i = index(e, key ": ")
	if (!i) return ""
	v = substr(e, i + length(key) + 2)
	if (substr(v, 1, 1) == "\"") return golit(v)
	sub(/[,}].*/, "", v)
	return v
}
function bool(v) { return v == "true" ? "true" : "false" }
/^var functions|gconFunctions = / { sect = "f"; next }
/^var keywords|gconKeywords = / { sect = "k"; next }
/^var predefined/ { sect = "p"; next }
/^\t?\}$/ { sect = ""; next }
sect != "" && /\{Name: / {
	e = substr($0, index($0, "{Name: "))
	name = field(e, "Name")
	if (sect == "f")
		init = sprintf("{%s, %s, %s, %s, %s, %s}", name, field(e, "Arity"),
			field(e, "Signature"), field(e, "Summary"), bool(field(e, "Graphics")),
			bool(field(e, "Gcon")))
	else if (sect == "k")
		init = sprintf("{%s, %s, %s}", name, field(e, "Summary"), bool(field(e, "Gcon")))
	else
		init = sprintf("{%s, %s}", name, field(e, "Feature"))
	printf "%s\t%s\t%s\n", sect, substr(name, 2, length(name) - 2), init
}' internal/builtin/catalog_gen.go internal/builtin/gcon.go >"$tmp/all"

# Functions and keywords sorted by name; predefined symbols in order.
grep '^f	' "$tmp/all" | LC_ALL=C sort -t '	' -k2,2 >"$tmp/f"
grep '^k	' "$tmp/all" | LC_ALL=C sort -t '	' -k2,2 >"$tmp/k"
grep '^p	' "$tmp/all" >"$tmp/p"
table() { cut -f3- "$1" | sed 's/^/	/; s/$/,/'; }
{
	echo "/* Generated by src/tests/genbuiltin.sh from the Go reference's"
	echo " * internal/builtin (from the Icon sources, and gcon's additions). */"
	echo
	echo "static const BuiltinFunc functions[] = {"
	table "$tmp/f"
	echo "};"
	echo
	echo "static const Keyword keywords[] = {"
	table "$tmp/k"
	echo "};"
	echo
	echo "static const Predefined predefined[] = {"
	table "$tmp/p"
	echo "};"
} >src/builtin.inc
echo "$(wc -l <"$tmp/f" | tr -d ' ') functions, $(wc -l <"$tmp/k" | tr -d ' ') keywords, $(wc -l <"$tmp/p" | tr -d ' ') predefined" >&2
